import numpy as np
from scipy.ndimage import label

def get_max_comp_periodic(k, a, b, size=20):
    grid = np.zeros((size, size), dtype=int)
    for x in range(size):
        for y in range(size):
            grid[x, y] = (a * x + b * y) % k

    max_comp_all_S = []
    for color in range(k):
        mask = (grid != color)
        labeled_array, num_features = label(mask)
        if num_features == 0:
            max_comp_all_S.append(0)
        else:
            component_sizes = np.bincount(labeled_array.ravel())
            max_comp_all_S.append(np.max(component_sizes[1:]))
    return max(max_comp_all_S)

for a in range(5):
    for b in range(5):
        print(f"a={a}, b={b}, max_comp={get_max_comp_periodic(3, a, b)}")

import numpy as np
from scipy.ndimage import label

def get_max_comp_all_S(grid, k):
    max_comp_all_S = []
    for color in range(k):
        mask = (grid != color)
        labeled_array, num_features = label(mask)
        if num_features == 0:
            max_comp_all_S.append(0)
        else:
            component_sizes = np.bincount(labeled_array.ravel())
            max_comp_all_S.append(np.max(component_sizes[1:]))
    return max(max_comp_all_S)

size = 20
grid = np.zeros((size, size), dtype=int)
for x in range(size):
    for y in range(size):
        if (x + y) % 2 == 0:
            grid[x, y] = 0
        elif x % 2 == 0:
            grid[x, y] = 1
        else:
            grid[x, y] = 2

print(f"Max comp size: {get_max_comp_all_S(grid, 3)}")
